'use strict';
const qs=(s,r=document)=>r.querySelector(s),qsa=(s,r=document)=>[...r.querySelectorAll(s)];
const html=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>'Rs '+(Number(v)/100).toLocaleString('en-PK',{maximumFractionDigits:2});
let when=v=>{const d=new Date(Number(v)),p=new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Karachi'}).formatToParts(d),get=t=>p.find(v=>v.type===t)?.value;return `${get('day')} ${get('month')}, ${get('year')} `+new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Karachi'}).format(d)+' PST'};
let staff=null,screenRun=0,projectDraft=null;
async function request(path,data){const r=await fetch(path,{method:data===undefined?'GET':'POST',credentials:'same-origin',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const result=await r.json();if(!r.ok)throw new Error(result.error||'Please retry.');return result}
const field=(name,label,value='',type='text',extra='')=>`<div class="field"><label for="o-${name}">${label}</label><input id="o-${name}" name="${name}" type="${type}" value="${html(value)}" ${extra}></div>`;
const box=(name,label,value='',numbered=false)=>`<div class="field full"><label for="o-${name}">${label}</label><textarea id="o-${name}" name="${name}" ${numbered?'data-numbered':''} rows="5">${html(Array.isArray(value)?value.map((v,i)=>(numbered?(i+1)+'. ':'')+v).join('\n'):value)}</textarea></div>`;
const options=(values,selected)=>values.map(v=>`<option value="${html(v)}" ${v===selected?'selected':''}>${html(v)}</option>`).join('');
const select=(name,label,values,value)=>`<div class="field"><label for="o-${name}">${label}</label><select name="${name}" id="o-${name}">${options(values,value)}</select></div>`;
function alertError(error){const el=qs('#staff-error');if(el){el.textContent=error.message||error;el.hidden=false;el.scrollIntoView({block:'nearest'})}}
function numbered(root=document){qsa('[data-numbered]',root).forEach(el=>{el.onfocus=()=>{if(!el.value.trim())el.value='1. '};el.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();el.setRangeText('\n'+(el.value.slice(0,el.selectionStart).split('\n').length+1)+'. ',el.selectionStart,el.selectionEnd,'end')}}})}
function notice(text){const el=qs('#staff-status');if(el){el.textContent=text;setTimeout(()=>{if(el.isConnected)el.textContent=''},5000)}}
function confirmStaff(title,fn){const d=qs('#staff-dialog');qs('#staff-dialog-content').innerHTML=`<h2>${html(title)}</h2><p>Please confirm this action.</p><p id="staff-confirm-error" role="alert"></p><div class="btn-row"><button type="button" class="btn btn-outline" id="staff-cancel">Cancel</button><button type="button" class="btn btn-accent" id="staff-confirm">Confirm</button></div>`;qs('#staff-cancel').onclick=()=>d.close();qs('#staff-confirm').onclick=async e=>{e.target.disabled=true;try{await fn();if(d.open)d.close()}catch(error){qs('#staff-confirm-error').textContent=error.message;e.target.disabled=false}};d.showModal()}
function formBind(selector,fn){const form=qs(selector);if(!form)return;form.onsubmit=async e=>{e.preventDefault();const b=qs('button[type=submit]',form);if(b)b.disabled=true;try{await fn(Object.fromEntries(new FormData(form)),form)}catch(error){alertError(error)}finally{if(b?.isConnected)b.disabled=false}}}
function authScreen(change=false){qs('#staff-app').innerHTML=`<section class="staff-auth"><a href="/" class="staff-wordmark">auctionhouse.pk</a><div class="panel"><small>OPERATIONS PORTAL</small><h1>${change?'Change initial password':'Administrator sign in'}</h1><p>${change?'Set your own password before accessing administrator modules.':'Use a separate administrator account.'}</p><p id="staff-error" class="form-error" hidden role="alert"></p><form id="staff-auth-form">${change?field('currentPassword','Current password','','password','required autocomplete="current-password"')+field('password','New password','','password','required  autocomplete="new-password"')+field('confirmPassword','Confirm new password','','password','required  autocomplete="new-password"'):field('username','Username','budapest','text','required autocomplete="username"')+field('password','Password','','password','required autocomplete="current-password"')}<button class="btn btn-accent" type="submit">${change?'Save password':'Sign in'}</button></form><a href="/">Return to website ↗</a></div></section>`;formBind('#staff-auth-form',async data=>{if(change){await request('/api/staff/password',data);staff=null;authScreen();qs('#staff-auth-form input[name=username]').value='budapest'}else{staff=(await request('/api/staff/login',data)).staff;if(staff.mustChange)authScreen(true);else routeStaff()}})}
const modules=[['projects','AH Projects','projects'],['reviews','Pending Listing Reviews','reviews'],['users','Users Management','users'],['closed-deals','View Closed Deals','deals'],['fee-deals','Fees & Settlement','finance'],['home','Page Settings','pages'],['settings','Account Settings','settings'],['admins','Administrator accounts','admins']];
function frame(module,title,body){qs('#staff-app').innerHTML=`<div class="staff-layout"><aside class="staff-sidebar"><a href="/budapest-admin" class="staff-wordmark">AH<span>OPERATIONS</span></a><nav aria-label="Admin modules">${modules.filter(m=>staff.permissions.includes(m[2])).map(([id,label])=>`<a href="/budapest-admin/${id}" class="${id===module?'active':''}">${label}</a>`).join('')}</nav><div class="staff-profile"><strong>${html(staff.username)}</strong><small>${html(staff.role)}</small><button type="button" id="staff-logout">Sign out</button><a href="/" target="_blank" rel="noopener">Open website ↗</a></div></aside><div class="staff-main"><div class="staff-heading"><div><small>AUCTIONHOUSE.PK / ADMINISTRATION</small><h1>${html(title)}</h1></div><span id="staff-status" role="status"></span></div><p id="staff-error" class="form-error" role="alert" hidden></p>${body}</div></div><dialog id="staff-dialog"><button type="button" id="staff-close" aria-label="Close">×</button><div id="staff-dialog-content"></div></dialog>`;qs('#staff-close').onclick=()=>qs('#staff-dialog').close();qs('#staff-logout').onclick=()=>confirmStaff('Sign out of administration?',async()=>{await request('/api/staff/logout',{});staff=null;authScreen()})}
async function routeStaff(){const run=++screenRun;try{staff=(await request('/api/staff/me')).staff;if(!staff){authScreen();return}if(staff.mustChange){authScreen(true);return}let module=location.pathname.split('/')[2]||modules.find(m=>staff.permissions.includes(m[2]))?.[0]||'password';if(module==='project-info'){await projectInfoScreen(run);return}if(module==='formats'){await formatsScreen(run);return}if(module==='general-terms'){await generalTermsScreen(run);return}if(module==='password'){frame('password','Change password',passwordForm());bindPassword();return}if(module==='projects')await projectScreen(run);else if(module==='reviews')await reviewScreen(run);else if(module==='users')await usersScreen(run);else if(module==='fee-deals'){history.replaceState({},'','/budapest-admin');await routeStaff();return}else if(module==='closed-deals')await closedScreen(run);else if(module==='home')await homeScreen(run);else if(module==='settings')await settingsScreen(run);else if(module==='admins')await adminsScreen(run);else{history.replaceState({},'','/budapest-admin');await routeStaff()}}catch(error){if(run===screenRun){if(!qs('#staff-error'))frame('','Unable to load this module','');alertError(error)}}}
const goStaff=path=>{history.pushState({},'',path);return routeStaff()};
async function projectScreen(run){const r=await request('/api/ops/projects');if(run!==screenRun)return;frame('projects','AH Projects',`<div class="staff-toolbar"><button class="btn btn-accent" id="new-project">Add New Project</button></div><div class="staff-project-list">${r.projects.filter(p=>p.status!=='deleted').map(p=>`<article class="panel"><img class="project-thumb" src="${html(p.images[0]||'/assets/pine-axis.webp')}" alt=""><h2>${html(p.name)}</h2><p>${html(p.scheme)} · ${html(p.status)}</p><p>${p.categories.length} categories · ${p.fields.length} configurable seller fields</p><button class="btn btn-black" data-edit-project="${p.id}">Edit Existing Project</button><button class="btn btn-outline" data-project-action="archive" data-id="${p.id}">Archive</button><button class="btn btn-danger" data-project-action="delete" data-id="${p.id}">Delete</button></article>`).join('')}</div>`);qs('#new-project').onclick=()=>editProject(null);qsa('[data-edit-project]').forEach(b=>b.onclick=()=>editProject(r.projects.find(p=>p.id===b.dataset.editProject)));qsa('[data-project-action]').forEach(b=>b.onclick=()=>confirmStaff(b.dataset.projectAction==='delete'?'Delete this project? Existing listings and history are retained.':'Archive this project?',async()=>{const p=r.projects.find(p=>p.id===b.dataset.id);await request('/api/ops/projects/'+p.id+'/'+b.dataset.projectAction,{confirm:true,version:p.version});await projectScreen(run)}))}
function defaultFields(){return [['scheme','Scheme','select'],['category','Category','select'],['allotment','Allotment Status','select'],['block','Block','select'],['plot','Plot number','select'],['facts','Facts for Auction','numbered'],['terms','Terms and Conditions for Auction','numbered'],['negotiationTerms','Terms and Conditions for Negotiation','numbered'],['features','Salient features','features'],['description','Description','numbered'],['unitMode','Per unit mode','select'],['price','Bid Starting Price (PKR)','number'],['bidInterval','Bid interval (PKR)','number'],['startsAt','Bidding start','datetime-local'],['endsAt','Bidding end','datetime-local'],['negotiationInterval','Negotiation interval (PKR)','number'],['negotiationMinutes','Negotiation response time (minutes)','number'],['holdingHours','Holding period (hours)','number'],['documents','Upload Documents','documents']].map(([key,label,type])=>({key,label,type,enabled:true,required:!['features','description','documents'].includes(key),...(['block','plot'].includes(key)?{condition:{field:'allotment',value:'Plot Allotted'}}:{})}))}
function readProject(){const form=qs('#project-form');if(!form)return projectDraft;const data=Object.fromEntries(new FormData(form));Object.assign(projectDraft,{name:data.name,scheme:data.scheme,scheme_options:String(data.schemeOptions||'').split('\n').map(v=>v.trim()).filter(Boolean),facts:data.facts,auction_terms:data.terms,negotiation_terms:data.negotiationTerms,deposit:Number(data.deposit||0)*100,sale_method:data.saleMethod,instalments:data.instalments});projectDraft.categories=qsa('.project-category',form).map(el=>({category:qs('.cat-name',el).value,marla:Number(qs('.cat-area',el).value),landUse:qs('.cat-land',el).value,blocks:Object.fromEntries(qsa('.project-block',el).map(b=>[qs('.block-name',b).value,qs('.block-plots',b).value.split(/[,\n]+/).map(v=>v.trim()).filter(Boolean)]))}));projectDraft.fields=qsa('.field-rule',form).map(el=>({key:qs('.rule-key',el).value,label:qs('.rule-label',el).value,type:qs('.rule-type',el).value,enabled:qs('.rule-enabled',el).checked,required:qs('.rule-required',el).checked,defaultValue:qs('.rule-default',el).value,options:qs('.rule-options',el).value.split('\n').filter(Boolean),...(qs('.rule-condition-field',el).value?{condition:{field:qs('.rule-condition-field',el).value,value:qs('.rule-condition-value',el).value}}:{})}));return projectDraft}
function editProject(p,retain=false){if(!retain)projectDraft=p?structuredClone(p):{name:'',scheme:'',scheme_options:[],categories:[{category:'',marla:8,landUse:'Commercial',blocks:{}}],images:[],facts:[],auction_terms:[],negotiation_terms:[],fields:defaultFields(),deposit:0,sale_method:'Ballot by LDA',instalments:'2 years'};const d=projectDraft;frame('projects',d.id?'Edit Existing Project':'Add New Project',`<form id="project-form" class="panel"><div class="form-grid">${field('name','Project Name',d.name,'text','required')}${field('scheme','Scheme',d.scheme,'text','required')}${box('schemeOptions','Scheme dropdown options (one per line; leave empty for a text field)',d.scheme_options)}${field('saleMethod','Sale Method',d.sale_method,'text','required')}${field('instalments','Instalment plan',d.instalments)}${field('deposit','Refundable Token Money (PKR)',d.deposit/100,'number','min="0" step="1"')}</div><h2>Categories, Blocks and Plots</h2><div id="category-builder">${d.categories.map((c,i)=>`<section class="project-category"><div class="category-heading"><label>Category<input class="cat-name" value="${html(c.category)}" required></label><label>Area (Marla)<input class="cat-area" type="number" min="1" value="${c.marla}" required></label><label>Land use<select class="cat-land">${options(['Commercial','Residential','Institutional','Others'],c.landUse)}</select></label><button type="button" class="btn btn-outline" data-remove-category="${i}">Remove category</button></div>${Object.entries(c.blocks).map(([name,plots],j)=>`<div class="project-block"><label>Block<input class="block-name" value="${html(name)}" required></label><label>Plots (comma or line separated)<textarea class="block-plots">${html(plots.join(', '))}</textarea></label><button type="button" class="btn btn-outline" data-remove-block="${i}:${j}">Remove block</button></div>`).join('')}<button type="button" class="btn btn-outline" data-add-block="${i}">+ Add Block, Plots</button></section>`).join('')}</div><button type="button" class="btn btn-outline" id="add-category">+ Add Category</button><h2>Project pictures</h2><p>Up to 5 pictures. Select the display picture.</p><input id="project-images" type="file" accept="image/jpeg,image/png,image/webp" multiple><div class="staff-image-grid">${d.images.map((url,i)=>`<label><img src="${html(url)}" alt="Picture ${i+1}"><span><input type="radio" name="projectDisplay" value="${i}" ${i===0?'checked':''}> Display picture</span><button type="button" data-remove-project-image="${i}">Remove</button></label>`).join('')}</div><h2>Project defaults</h2>${box('facts','Facts',d.facts,true)}${box('terms','Terms and Conditions of Auction',d.auction_terms,true)}${box('negotiationTerms','Terms and Conditions of Negotiation',d.negotiation_terms,true)}<h2>Seller field configuration</h2><p>Use the arrows to change field order. Conditions refer to a field above the current field. Disabled fields use the project default; required fields must have a value. You can label fields and configure dropdown options and defaults.</p><div id="field-rules">${d.fields.map((f,i)=>`<section class="field-rule"><div class="rule-heading"><button type="button" data-move-rule="${i}:-1" aria-label="Move field up">↑</button><button type="button" data-move-rule="${i}:1" aria-label="Move field down">↓</button><label>Field key<input class="rule-key" value="${html(f.key)}" required></label><label>Label<input class="rule-label" value="${html(f.label)}" required></label><label>Type<select class="rule-type">${options(['text','select','numbered','number','datetime-local','features','documents'],f.type)}</select></label></div><div class="rule-options-row"><label><input type="checkbox" class="rule-enabled" ${f.enabled?'checked':''}> Enabled</label><label><input type="checkbox" class="rule-required" ${f.required?'checked':''}> Required</label><label>Default value<input class="rule-default" value="${html(f.defaultValue||'')}"></label><label>Dropdown options<textarea class="rule-options">${html((f.options||[]).join('\n'))}</textarea></label><label>Show when field<select class="rule-condition-field"><option value="">Always</option>${d.fields.slice(0,i).map(v=>`<option value="${v.key}" ${f.condition?.field===v.key?'selected':''}>${html(v.label)}</option>`).join('')}</select></label><label>Equals<input class="rule-condition-value" value="${html(f.condition?.value||'')}"></label></div></section>`).join('')}</div><button type="button" class="btn btn-outline" id="add-field-rule">+ Add Field</button><div class="staff-toolbar"><button class="btn btn-accent" type="submit">Save Project</button><button class="btn btn-outline" type="button" id="cancel-project">Cancel</button></div></form>`);numbered();qs('#cancel-project').onclick=()=>routeStaff();qs('#add-category').onclick=()=>{readProject().categories.push({category:'',marla:8,landUse:'Commercial',blocks:{}});editProject(null,true)};qsa('[data-add-block]').forEach(b=>b.onclick=()=>{const d=readProject(),i=Number(b.dataset.addBlock);d.categories[i].blocks['New Block '+(Object.keys(d.categories[i].blocks).length+1)]=[];editProject(null,true)});qsa('[data-remove-block]').forEach(b=>b.onclick=()=>{const d=readProject(),[i,j]=b.dataset.removeBlock.split(':').map(Number);delete d.categories[i].blocks[Object.keys(d.categories[i].blocks)[j]];editProject(null,true)});qsa('[data-remove-category]').forEach(b=>b.onclick=()=>{readProject().categories.splice(Number(b.dataset.removeCategory),1);editProject(null,true)});qsa('[data-move-rule]').forEach(b=>b.onclick=()=>{const d=readProject(),[i,dir]=b.dataset.moveRule.split(':').map(Number),j=i+dir;if(j<0||j>=d.fields.length)return;[d.fields[i],d.fields[j]]=[d.fields[j],d.fields[i]];editProject(null,true)});qs('#add-field-rule').onclick=()=>{readProject().fields.push({key:'field'+(projectDraft.fields.length+1),label:'New Field',type:'text',enabled:true,required:false});editProject(null,true)};qsa('[data-remove-project-image]').forEach(b=>b.onclick=()=>{readProject().images.splice(Number(b.dataset.removeProjectImage),1);editProject(null,true)});qs('#project-images').onchange=async e=>{try{readProject();if(d.images.length+e.target.files.length>5)throw new Error('Use up to 5 pictures.');notice('Uploading pictures…');for(const file of e.target.files){const form=new FormData();form.set('file',file);form.set('kind','image');form.set('scope','staff');const res=await fetch('/api/uploads',{method:'POST',body:form,credentials:'same-origin'}),result=await res.json();if(!res.ok)throw new Error(result.error);d.images.push(result.url)}editProject(null,true)}catch(e){alertError(e)}};formBind('#project-form',async()=>{const display=Number(qs('[name=projectDisplay]:checked')?.value||0),d=readProject(),images=[d.images[display],...d.images.filter((_,i)=>i!==display)].filter(Boolean);await request('/api/ops/projects'+(d.id?'/'+d.id:''),{name:d.name,scheme:d.scheme,schemeOptions:d.scheme_options,categories:d.categories,images,facts:d.facts,terms:d.auction_terms,negotiationTerms:d.negotiation_terms,fields:d.fields,deposit:d.deposit/100,saleMethod:d.sale_method,instalments:d.instalments,version:d.version});await routeStaff()})}
async function reviewScreen(run){const r=await request('/api/ops/review');if(run!==screenRun)return;frame('reviews','Pending Listing Reviews',r.listings.length?r.listings.map(l=>`<article class="panel review-listing" data-review-id="${l.id}"><h2>${html(l.title)}</h2><p>${html(l.display_id)} · ${html(l.address)}</p><p>Seller: ${html(l.seller_name)} · ${html(l.seller_email)}</p><p>Area: ${l.sqft.toLocaleString()} sq ft · ${html(l.land_use)} · Starting price: ${money(l.starting_price)} (${html(l.unit_mode)})</p><div class="staff-image-grid">${l.gallery.map(u=>`<a href="${html(u)}" target="_blank" rel="noopener"><img src="${html(u)}" alt="Property picture"></a>`).join('')}</div>${[['Salient features',l.features],['Description',l.description],['Facts',l.facts],['Auction terms',l.terms],['Negotiation terms',l.negotiation_terms]].filter(([,v])=>v?.length).map(([label,values])=>`<h3>${label}</h3><ol>${values.map(v=>'<li>'+html(v)+'</li>').join('')}</ol>`).join('')}<label><input type="checkbox" class="documents-verified"> I have verified the ownership documents (show public badge)</label><h3>Uploaded documents</h3>${l.documents.map((id,i)=>`<a class="btn btn-outline" href="/api/media/${id}" target="_blank" rel="noopener">Document ${i+1} ↗</a>`).join('')||'<p>No documents supplied.</p>'}<div class="field"><label>Note to seller<textarea class="review-note-input" rows="4">${html(l.review_note||'')}</textarea></label></div><div class="btn-row"><button class="btn btn-accent" data-review-action="approve">Approve listing</button><button class="btn btn-outline" data-review-action="note">Request changes / documents</button><button class="btn btn-danger" data-review-action="reject">Reject</button></div></article>`).join(''):'<div class="panel">No listings awaiting review.</div>');qsa('[data-review-action]').forEach(b=>b.onclick=()=>{const card=b.closest('[data-review-id]'),l=r.listings.find(l=>l.id===card.dataset.reviewId);confirmStaff(b.dataset.reviewAction==='approve'?'Confirm ownership review and publish this listing?':b.dataset.reviewAction==='note'?'Send this request to the seller?':'Reject this listing?',async()=>{await request('/api/ops/review/'+l.id,{action:b.dataset.reviewAction,documentsVerified:!!qs('.documents-verified',card)?.checked,note:qs('.review-note-input',card).value,version:l.version,confirm:true});await reviewScreen(run)})})}
async function usersScreen(run,query=''){const r=await request('/api/ops/users?q='+encodeURIComponent(query));if(run!==screenRun)return;frame('users','Users Management',`<form id="user-search" class="staff-toolbar"><label>Search customers<input name="q" value="${html(query)}" placeholder="Name or email"></label><button type="submit" class="btn btn-outline">Search</button></form><div class="staff-users">${r.users.map(u=>`<article class="panel" data-account="${u.id}"><h2>${html(u.full_name)}</h2><p>${html(u.email)} · ${html(u.phone)}</p><div class="balance-summary"><div><small>Total</small><strong>${money(u.balance)}</strong></div><div><small>Reserved</small><strong>${money(u.reserved)}</strong></div><div><small>Available</small><strong>${money(u.available)}</strong></div></div><details><summary>Customer details</summary><dl><dt>Account ID</dt><dd>${html(u.id)}</dd><dt>Father’s name</dt><dd>${html(u.father_name)}</dd><dt>CNIC</dt><dd>${html(u.cnic)}</dd><dt>Address</dt><dd>${html(u.address)}</dd><dt>Sign-in</dt><dd>${u.googleAccount?'Google':'Email and password'}</dd><dt>Registered</dt><dd>${when(u.created_at)}</dd></dl></details>${staff.permissions.includes('finance')?`<form class="credit-form"><h3>Record cash received or returned</h3>${select('direction','Cash entry type',['Cash received','Cash returned'],'Cash received')}<div class="form-grid">${field('amount','Amount (PKR)','','number','min="0.01" step="0.01" required')}${field('reference','Unique receipt reference','','text','required')}${field('note','Receipt note','','text','required ')}</div><button class="btn btn-accent" type="submit">Record cash entry</button></form>`:''}</article>`).join('')}</div>`);formBind('#user-search',async data=>usersScreen(run,data.q));qsa('.credit-form').forEach(form=>form.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form)),accountId=form.closest('[data-account]').dataset.account;confirmStaff('Confirm this cash was '+(data.direction==='Cash returned'?'returned':'received')+': PKR '+data.amount+'?',async()=>{await request(data.direction==='Cash returned'?'/api/ops/refund':'/api/ops/credit',{...data,accountId});await usersScreen(run,query)})})}
async function closedScreen(run){const r=await request('/api/ops/closed-deals');if(run!==screenRun)return;frame('closed-deals','View Closed Deals',r.deals.length?r.deals.map(d=>{const l=JSON.parse(d.snapshot),checks=JSON.parse(d.checklist);return `<article class="panel closed-review" data-closed-id="${html(d.id)}"><h2>${html(l.title)}</h2><p>${html(l.address)} · ${money(d.amount)} (${html(d.unit_mode)})</p><p>Accepted: ${when(d.created_at)}</p><p>Buyer: ${html(d.buyer_name)} · ${html(d.buyer_email)} · ${html(d.buyer_phone)}</p><p>Seller: ${html(d.seller_name)} · ${html(d.seller_email)} · ${html(d.seller_phone)}</p><form class="closed-checklist">${[['buyerContacted','Buyer contacted'],['sellerContacted','Seller contacted'],['dealFinalized','Deal Finalized'],['documentationCompleted','Documentation completed']].map(([key,label])=>`<label><input name="${key}" type="checkbox" ${checks[key]?'checked':''}> ${label}</label>`).join('')}<button class="btn btn-accent" type="submit">Save checklist</button>${staff.permissions.includes('finance')?'<button type="button" class="btn btn-outline" data-release>Release completed-deal deposit reservations</button>':''}</form></article>`}).join(''):'<div class="panel">No accepted deals yet.</div>');qsa('.closed-checklist').forEach(form=>{const id=form.closest('[data-closed-id]').dataset.closedId,d=r.deals.find(v=>v.id===id);form.onsubmit=async e=>{e.preventDefault();try{const checklist=Object.fromEntries(qsa('input[type=checkbox]',form).map(el=>[el.name,el.checked]));await request('/api/ops/closed-deals/'+encodeURIComponent(id),{version:d.version,checklist});await closedScreen(run)}catch(e){alertError(e)}};qs('[data-release]',form)?.addEventListener('click',()=>confirmStaff('Release participation reservations after documentation completion?',async()=>{await request('/api/ops/release-deposit',{dealId:id,confirm:true});notice('Deposit reservations released.')}))})}
async function homeScreen(run){const r=await request('/api/ops/home');if(run!==screenRun)return;const p=r.page;frame('home','Page Settings',`<form id="home-projects" class="panel"><h2>Home content and search previews</h2>${field('title','Page title',p.title)}${box('description','Search and link-preview description',p.description)}${field('heading','Home heading',p.heading)}${box('intro','Home introduction',p.intro)}${field('banner','Optional date banner',p.banner)}${field('deadline','Banner deadline (include timezone, e.g. 2026-12-03T17:00:00+05:00)',p.deadline?new Date(p.deadline).toISOString():'')}<p>The banner is hidden when its deadline has passed. Leave it empty to show no dated promotion.</p><h2>Home page projects</h2>${r.projects.filter(p=>p.status==='active').map(p=>`<div class="home-project" data-project-id="${p.id}"><label><input class="home-visible" type="checkbox" ${p.home_visible?'checked':''}> ${html(p.name)}</label><label>Position<input class="home-order" type="number" min="0" max="1000" value="${p.home_order}"></label></div>`).join('')}<button class="btn btn-accent" type="submit">Save home page placement</button></form>`);formBind('#home-projects',async data=>{const deadline=data.deadline?Date.parse(data.deadline):0;if(!Number.isFinite(deadline))throw new Error('Enter a valid deadline with a timezone.');await request('/api/ops/home',{page:{title:data.title,description:data.description,heading:data.heading,intro:data.intro,banner:data.banner,deadline},projects:qsa('.home-project').map(el=>({id:el.dataset.projectId,visible:qs('.home-visible',el).checked,order:Number(qs('.home-order',el).value)}))});notice('Home page content and placement saved.')})}
function passwordForm(){return `<form id="staff-password-form" class="panel"><h2>Change administrator password</h2>${field('currentPassword','Current password','','password','required autocomplete="current-password"')}${field('password','New password','','password','required  autocomplete="new-password"')}${field('confirmPassword','Confirm password','','password','required ')}<button class="btn btn-black" type="submit">Change password</button></form>`}
