async function settingsScreen(run){const r=await request('/api/ops/settings');if(run!==screenRun)return;const s=r.settings,c=s.contact;frame('settings','Account Settings',`<form id="site-settings" class="panel"><h2>Contact Us</h2><div class="form-grid">${field('email','Email ID',c.email,'email','required')}${field('phone','WhatsApp and mobile',c.phone)}${box('address','Office address',c.address)}${field('hours','Office working hours',c.hours)}${field('mapLink','Google Maps location link',c.mapLink,'url')}${field('mapEmbed','Google Maps embed URL',c.mapEmbed,'url')}</div><h2>About Us</h2>${box('about','About Us text',s.about)}<h2>How it Works</h2><div id="how-steps">${(s.how||[]).map(step=>`<div class="how-step"><label>Step heading<input class="how-title" value="${html(step.title)}" required></label><label>Step text<textarea class="how-body" required>${html(step.body)}</textarea></label><button type="button" class="btn btn-outline remove-how">Remove step</button></div>`).join('')}</div><button type="button" class="btn btn-outline" id="add-how-step">+ Add step</button><h2>Indicative buyer fee estimate</h2>${field('buyerFeeBps','Buyer fee basis points (50-200; leave empty for unconfigured)',s.buyerFeeBps??'','number','min="50" max="200" step="1"')}<p>100 basis points = 1%. This only configures the public calculator. Issued fee agreements remain unchanged.</p><h2>Participation balance settings</h2>${field('customDeposit','Default Refundable Token Money for custom listings (PKR)',s.customDeposit/100,'number','min="0" step="1"')}<p>Project-specific deposits are configured in AH Projects. Amounts are reserved from available customer cash balances, and remain separate from fee settlements.</p><p>Email notifications: ${r.emailConfigured?'provider configured':'configure RESEND_API_KEY and EMAIL_FROM to deliver queued messages'}</p><button class="btn btn-accent" type="submit">Save Account Settings</button></form><h2>Administrator security alerts</h2><form id="security-email-form" class="panel">${field('securityEmail','Your security email',staff.email||'','email','required')}<p>All enabled staff with a configured email receive an alert when an administrator signs in from a new device.</p><button class="btn btn-accent" type="submit">Save security email</button></form>${passwordForm()}`);formBind('#security-email-form',async data=>{await request('/api/staff/email',{email:data.securityEmail});staff.email=data.securityEmail;notice('Security email saved.')});const bindRemove=()=>qsa('.remove-how').forEach(b=>b.onclick=()=>b.closest('.how-step').remove());bindRemove();qs('#add-how-step').onclick=()=>{const div=document.createElement('div');div.className='how-step';div.innerHTML='<label>Step heading<input class="how-title" required></label><label>Step text<textarea class="how-body" required></textarea></label><button type="button" class="btn btn-outline remove-how">Remove step</button>';qs('#how-steps').append(div);bindRemove()};formBind('#site-settings',async data=>{await request('/api/ops/settings',{contact:{email:data.email,phone:data.phone,address:data.address,hours:data.hours,mapLink:data.mapLink,mapEmbed:data.mapEmbed},about:data.about,how:qsa('.how-step').map(el=>({title:qs('.how-title',el).value,body:qs('.how-body',el).value})),buyerFeeBps:data.buyerFeeBps,customDeposit:Number(data.customDeposit)});notice('Contact details and website text saved.')});bindPassword()}
async function adminsScreen(run){const r=await request('/api/ops/admins');if(run!==screenRun)return;frame('admins','Administrator accounts',`<div class="panel"><h2>Existing administrators</h2><div class="wide-table"><table><thead><tr><th>Username</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody>${r.admins.map(a=>`<tr><td>${html(a.username)}</td><td>${html(a.role)}</td><td>${a.disabled?'Disabled':a.must_change?'Password change required':'Active'}</td><td>${a.id!==staff.id&&!a.disabled?`<button class="btn btn-outline" data-disable-admin="${a.id}">Disable</button>`:''}</td></tr>`).join('')}</tbody></table></div></div><form id="new-admin" class="panel"><h2>Create new administrator</h2>${field('username','Username','','text','required pattern="[a-z][a-z0-9._-]+"')}${field('email','Security notification email','','email','required')}${select('role','Role',Object.keys(r.roles),'reviewer')}${field('password','Initial password','','password','required ')}${field('confirmPassword','Confirm password','','password','required ')}<p>New administrators must change their initial password. Customer email accounts do not grant administrator access.</p><button type="submit" class="btn btn-accent">Create administrator</button></form><form class="panel" id="new-role"><h2>Define a role</h2>${field('name','Role name','','text','required pattern="[a-z][a-z0-9_-]+"')}<div class="role-permissions">${['projects','reviews','users','finance','deals','pages','settings','admins'].map(p=>`<label><input type="checkbox" name="permission" value="${p}"> ${p}</label>`).join('')}</div><button type="submit" class="btn btn-accent">Save role</button></form><div class="panel"><h2>Role permissions</h2>${Object.entries(r.roles).map(([role,permissions])=>`<p><strong>${html(role)}</strong>: ${permissions.map(html).join(', ')}</p>`).join('')}</div>`);formBind('#new-role',async(data,form)=>{await request('/api/ops/roles',{name:data.name,permissions:new FormData(form).getAll('permission')});await adminsScreen(run)});formBind('#new-admin',async data=>{await request('/api/ops/admins',data);await adminsScreen(run)});qsa('[data-disable-admin]').forEach(b=>b.onclick=()=>confirmStaff('Disable this administrator and revoke their sessions?',async()=>{await request('/api/ops/admins/'+b.dataset.disableAdmin+'/disable',{confirm:true});await adminsScreen(run)}))}
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||a.target||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||e.button!==0)return;const u=new URL(a.href,location.origin);if(u.origin===location.origin&&u.pathname.startsWith('/admin')){e.preventDefault();goStaff(u.pathname.startsWith('/admin/deal/')?'/budapest-admin/fee-deals/'+u.pathname.split('/').pop():'/budapest-admin');return}if(u.origin===location.origin&&u.pathname.startsWith('/budapest-admin')){e.preventDefault();goStaff(u.pathname+u.search)}},true);addEventListener('popstate',()=>routeStaff());routeStaff();

