when=v=>siteStaffDate(v);function siteStaffDate(v){const d=new Date(Number(v)),p=new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Karachi'}).formatToParts(d),part=k=>p.find(x=>x.type===k)?.value;return `${part('day')} ${part('month')}, ${part('year')} `+new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',hour12:true,timeZone:'Asia/Karachi'}).format(d).toUpperCase()+' PST'}
