async function generalTermsScreen(run){const r=await request('/api/ops/general-terms');if(run!==screenRun)return;frame('general-terms','General Facts and Terms',`<form id="general-terms" class="panel"><p>These defaults are prefilled for new custom properties. Sellers may edit or add items before submission.</p>${box('facts','General Facts for Auction',r.general.facts,true)}${box('terms','General Terms and Conditions of Auction',r.general.terms,true)}${box('negotiationTerms','General Terms and Conditions of Negotiation',r.general.negotiationTerms,true)}<button class="btn btn-accent" type="submit">Save general defaults</button></form>`);numbered();formBind('#general-terms',async data=>{await request('/api/ops/general-terms',data);notice('General facts and terms saved.')})}
usersScreen=async function(run){const params=new URLSearchParams(location.search),id=location.pathname.split('/')[3];if(id){await userDetailScreen(run,id);return}const r=await request('/api/ops/users?'+params);if(run!==screenRun)return;const columns=[['id','User ID'],['cnic','CNIC'],['name','Name'],['balance','Available Balance'],['properties','Active Listings'],['bids','Active Biddings'],['activity','Last activity']],sort=key=>{const p=new URLSearchParams(params);p.set('sort',key);p.set('direction',params.get('sort')===key&&params.get('direction')==='asc'?'desc':'asc');p.delete('page');return '/budapest-admin/users?'+p};const exportParams=new URLSearchParams(params);exportParams.set('export','1');frame('users','Users Management',`<form id="user-search" class="staff-toolbar"><label>Search users<input name="q" value="${html(params.get('q')||'')}" placeholder="User ID, CNIC, name, email or mobile"></label><label>Activity filter<select name="active">${options(['','properties','bids'],params.get('active')||'')}</select></label><label>Users per page<select name="size">${options(['25','50','100','250','500','1000'],String(r.size))}</select></label><button class="btn btn-outline" type="submit">Search / apply</button><a class="btn btn-black" href="/api/ops/users?${html(exportParams)}" download>Download filtered Excel</a><a class="btn btn-outline" href="/api/ops/users?export=1" download>Download all users Excel</a></form><div class="wide-table"><table class="user-table"><thead><tr>${columns.map(([key,title])=>'<th><a href="'+html(sort(key))+'">'+title+' '+((params.get('sort')||'activity')===key?(params.get('direction')==='asc'?'↑':'↓'):'↕')+'</a></th>').join('')}</tr></thead><tbody>${r.users.map(u=>`<tr data-user-row="${html(u.id)}" tabindex="0"><td><a href="/budapest-admin/users/${html(u.id)}">${html(u.public_id)}</a></td><td>${html(u.cnic)}</td><td>${html(u.full_name)}</td><td>${money(u.available)}</td><td>${u.active_properties}</td><td>${u.active_bids}</td><td>${when(u.last_activity||u.created_at)}</td></tr>`).join('')}</tbody></table></div><div class="staff-toolbar">${r.page>1?'<button class="btn btn-outline" data-user-page="'+(r.page-1)+'">Previous</button>':''}<p>${r.total} users · Page ${r.page} of ${r.pages}</p>${r.page<r.pages?'<button class="btn btn-outline" data-user-page="'+(r.page+1)+'">Next</button>':''}</div>`);formBind('#user-search',async data=>{const p=new URLSearchParams({...Object.fromEntries(params),...data});p.delete('page');goStaff('/budapest-admin/users?'+p)});qsa('[data-user-row]').forEach(row=>{row.onclick=e=>{if(!e.target.closest('a'))goStaff('/budapest-admin/users/'+row.dataset.userRow)};row.onkeydown=e=>{if(e.key==='Enter')goStaff('/budapest-admin/users/'+row.dataset.userRow)}});qsa('[data-user-page]').forEach(b=>b.onclick=()=>{const p=new URLSearchParams(params);p.set('page',b.dataset.userPage);goStaff('/budapest-admin/users?'+p)})};
async function userDetailScreen(run,id){const r=await request('/api/ops/users/'+encodeURIComponent(id));if(run!==screenRun)return;const u=r.user;frame('users','User '+u.public_id,`<a href="/budapest-admin/users">← Users</a><article class="panel"><h2>${html(u.full_name)}</h2><p>User ID: ${html(u.public_id)}</p><dl><dt>CNIC</dt><dd>${html(u.cnic)}</dd><dt>Email</dt><dd>${html(u.email)}</dd><dt>Mobile</dt><dd>${html(u.phone)}</dd><dt>Address</dt><dd>${html(u.address)}</dd><dt>Father’s name</dt><dd>${html(u.father_name)}</dd></dl><p>Available balance: ${money(u.available)} · Reserved: ${money(u.reserved)} · Total: ${money(u.balance)}</p><p>Last activity: ${when(u.last_activity||u.created_at)}</p></article>${staff.permissions.includes('finance')?`<form id="user-cash" class="panel"><h2>Record cash</h2>${select('direction','Cash type',['Cash received','Cash returned'],'Cash received')}${field('amount','Amount PKR','','number','min="0.01" step="0.01" required')}${field('reference','Receipt reference','','text','required')}${field('note','Note','','text','required')}<button class="btn btn-accent" type="submit">Record cash</button></form>`:''}<div class="panel"><h2>Cash records</h2><table><thead><tr><th>Amount</th><th>Reference</th><th>Date</th><th></th></tr></thead><tbody>${r.entries.map(e=>`<tr><td>${e.direction==='debit'?'Returned':'Received'} ${money(e.corrected_amount??e.amount)}</td><td>${html(e.reference)}</td><td>${when(e.created_at)}</td><td>${staff.permissions.includes('finance')?'<button class="btn btn-outline" data-edit-cash="'+html(e.id)+'">Edit cash record</button>':''}</td></tr>`).join('')}</tbody></table></div><article class="panel"><h2>Properties</h2>${r.properties.map(l=>'<p>'+html(l.display_id)+' · '+html(l.title)+' · '+html(l.status)+'</p>').join('')||'<p>None</p>'}<h2>Participated biddings</h2>${r.bids.map(l=>'<p>Property ID: '+html(l.display_id)+' · '+html(l.title)+' · Bidding ID: '+html(l.bidder_code)+' · '+money(l.highest_bid)+'</p>').join('')||'<p>None</p>'}<h2>Closed deals</h2>${r.deals.map(d=>'<p>'+html(JSON.parse(d.snapshot).title)+' · '+money(d.final_total||d.amount)+' · '+when(d.created_at)+'</p>').join('')||'<p>None</p>'}</article>`);qs('.staff-main').insertAdjacentHTML('beforeend','<section class="user-delete-zone"><h2>Permanently delete this user</h2><p>Clear outstanding commitments and balances first. Personal information and access are removed; anonymous financial records remain.</p><button class="btn btn-danger" id="delete-user">Permanently delete user</button></section>');qs('#delete-user').onclick=()=>deleteUserPrompt(id);formBind('#user-cash',async data=>{await request('/api/ops/'+(data.direction==='Cash returned'?'refund':'credit'),{...data,accountId:id});await userDetailScreen(run,id)});qsa('[data-edit-cash]').forEach(b=>b.onclick=()=>{const entry=r.entries.find(e=>e.id===b.dataset.editCash),d=qs('#staff-dialog');qs('#staff-dialog-content').innerHTML='<h2>Edit cash record</h2><p>A correction preserves the original receipt and updates the balance by the difference.</p><form id="cash-correction">'+field('amount','Corrected total amount (PKR)',(entry.corrected_amount??entry.amount)/100,'number','min="0" step="0.01" required')+field('reference','Unique correction reference','','text','required')+box('note','Reason for correction','')+'<button class="btn btn-accent" type="submit">Confirm correction</button></form>';formBind('#cash-correction',async data=>{await request('/api/ops/cash-correction',{...data,entryId:entry.id,revision:entry.correction_id||entry.id,confirm:true});d.close();await userDetailScreen(run,id)});d.showModal()})}
projectScreen=async function(run){const r=await request('/api/ops/projects');if(run!==screenRun)return;frame('projects','AH Projects','<button id="new-project" class="btn btn-accent">Add New Project</button><div class="staff-project-list">'+r.projects.filter(p=>p.status!=='deleted').map(p=>`<article class="panel"><img class="project-thumb" src="${html(p.images[0])}" alt=""><h2>${html(p.name)}</h2><label><input type="checkbox" data-project-enabled="${html(p.id)}" ${p.status==='active'?'checked':''}> Enable / Show project</label><p>Refundable Token Money: ${money(p.deposit)}</p><button class="btn btn-black" data-edit-project="${html(p.id)}">Edit Existing Project</button><button class="btn btn-danger" data-delete-project="${html(p.id)}">Delete</button></article>`).join('')+'</div>');qs('#new-project').onclick=()=>editProject(null);qsa('[data-edit-project]').forEach(b=>b.onclick=()=>editProject(r.projects.find(p=>p.id===b.dataset.editProject)));qsa('[data-project-enabled]').forEach(b=>b.onchange=()=>{const p=r.projects.find(p=>p.id===b.dataset.projectEnabled),enabled=b.checked;b.checked=!enabled;confirmStaff(enabled?'Enable this project?':'Hide this project from selection?',async()=>{await request('/api/ops/projects/'+p.id+'/toggle',{enabled,confirm:true,version:p.version});await projectScreen(run)})});qsa('[data-delete-project]').forEach(b=>b.onclick=()=>{const p=r.projects.find(p=>p.id===b.dataset.deleteProject);confirmStaff('Delete this project? Transaction history remains.',async()=>{await request('/api/ops/projects/'+p.id+'/delete',{version:p.version,confirm:true});await projectScreen(run)})})};
const nov8EditProject=editProject;editProject=function(p,retain=false){nov8EditProject(p,retain);qsa('.field-rule').forEach((rule,i)=>{const b=document.createElement('button');b.type='button';b.className='btn btn-outline';b.textContent='Delete field';rule.append(b);b.onclick=()=>{const d=readProject(),key=d.fields[i].key;d.fields.splice(i,1);d.fields.forEach(f=>{if(f.condition?.field===key)delete f.condition});editProject(null,true)}})};
reviewScreen=async function(run){const r=await request('/api/ops/review');if(run!==screenRun)return;const fields=[['title','Property title'],['address','Address'],['plot','Plot number'],['block','Block'],['scheme','Scheme'],['sector','Sector'],['category','Category'],['land_use','Land use'],['construction','Construction'],['allotment','Allotment'],['sqft','Area in sq ft'],['unit_mode','Price unit'],['starting_price','Starting price (PKR)'],['interval1','Bid interval (PKR)'],['negotiation_interval','Negotiation interval (PKR)'],['negotiation_time','Negotiation time (minutes)'],['holding_period','Holding period (hours)'],['starts_at','Bidding opens (Pakistan time)'],['ends_at','Bidding closes (Pakistan time)'],['facts','Facts'],['terms','Auction terms'],['negotiation_terms','Negotiation terms'],['description','Description'],['features','Salient features']];const factor=k=>['starting_price','interval1','negotiation_interval'].includes(k)?100:k==='negotiation_time'?60000:k==='holding_period'?3600000:1;frame('reviews','Pending Listing Reviews',r.listings.map(l=>`<article class="panel review-listing" data-review-id="${html(l.id)}"><h2>${html(l.title)}</h2><p>Property ID: ${html(l.display_id)} · Seller: ${html(l.seller_name)}</p><p>Review state: ${html(l.review_state)}</p>${l.admin_draft?'<p class="review-note">Awaiting seller response to highlighted changes.</p>':''}<div class="staff-image-grid">${l.gallery.map(u=>'<img src="'+html(u)+'" alt="Property">').join('')}</div><details><summary>Edit property entries and propose changes</summary><div class="form-grid">${fields.map(([key,label])=>{const value=l[key]??'';if(Array.isArray(value))return '<label>'+label+'<textarea data-review-field="'+key+'">'+html(value.join('\n'))+'</textarea></label>';if(['starts_at','ends_at'].includes(key))return '<label>'+label+'<input type="datetime-local" data-review-field="'+key+'" value="'+new Date(value+5*3600000).toISOString().slice(0,16)+'"></label>';return '<label>'+label+'<input data-review-field="'+key+'" '+(typeof value==='number'?'type="number" step="any"':'')+' value="'+html(typeof value==='number'?value/factor(key):value)+'"></label>'}).join('')}</div><button class="btn btn-outline" data-review-action="draft">Send changed draft to seller</button></details><h3>Supporting PDFs</h3>${l.documents.map((id,i)=>'<a class="btn btn-outline" target="_blank" rel="noopener" href="/api/media/'+html(id)+'">Document '+(i+1)+'</a>').join('')||'<p>No documents uploaded.</p>'}<label><input type="checkbox" class="documents-verified"> I verified ownership documents</label><section class="token-configuration"><h3>Refundable Token Money</h3><p>Set and send the money requirement independently of property changes and observations.</p><form data-token-form><label>Amount (PKR)<input name="amount" class="review-token" type="number" min="0.01" step="0.01" required value="${l.participation_deposit/100}" ></label><button class="btn btn-black" type="submit">Send Token Money requirement</button></form></section><label>Observations of Auction House (optional for drafts)<textarea class="review-note-input">${html(l.review_note||'')}</textarea></label>${l.draft_note?'<p>'+html(l.draft_note)+'</p>':''}<div class="btn-row"><button class="btn btn-accent" data-review-action="approve">Approve listing</button><button class="btn btn-outline" data-review-action="note">Send observations</button><button class="btn btn-danger" data-review-action="reject">Reject listing</button></div></article>`).join('')||'<div class="panel">No listings awaiting review.</div>');qsa('[data-token-form]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const card=form.closest('[data-review-id]'),l=r.listings.find(v=>v.id===card.dataset.reviewId),amount=qs('[name=amount]',form).value;confirmStaff('Send this Refundable Token Money requirement to the seller?',async()=>{await request('/api/ops/review/'+l.id,{action:'token',amount,version:l.version,confirm:true});await reviewScreen(run)})});qsa('[data-review-action]').forEach(b=>b.onclick=()=>{const card=b.closest('[data-review-id]'),l=r.listings.find(v=>v.id===card.dataset.reviewId);confirmStaff(b.dataset.reviewAction==='draft'?'Send a proposed draft for seller acceptance?':'Confirm this property review?',async()=>{const changes={};qsa('[data-review-field]',card).forEach(el=>{const k=el.dataset.reviewField;changes[k]=Array.isArray(l[k])?el.value.split('\n').filter(Boolean):['starts_at','ends_at'].includes(k)?Date.parse(el.value+'+05:00'):typeof l[k]==='number'?Math.round(Number(el.value)*factor(k)):el.value});await request('/api/ops/review/'+l.id,{action:b.dataset.reviewAction,changes,note:qs('.review-note-input',card).value,documentsVerified:qs('.documents-verified',card).checked,confirm:true,version:l.version});await reviewScreen(run)})})};
const nov8HomeSettings=homeScreen;homeScreen=async function(run){await nov8HomeSettings(run);if(run!==screenRun)return;const r=await request('/api/ops/home');qsa('.home-project').forEach(el=>{const p=r.projects.find(p=>p.id===el.dataset.projectId);el.insertAdjacentHTML('beforeend','<label>Marketplace tab position<input type="number" class="market-order" min="0" max="1000" value="'+p.market_order+'"></label>')});qs('#home-projects').insertAdjacentHTML('beforeend','<h2>Featured Marketplace properties</h2>'+r.featured.map(l=>'<label class="featured-choice"><input type="checkbox" data-featured-id="'+html(l.id)+'" '+(l.featured?'checked':'')+'> '+html(l.display_id)+' · '+html(l.title)+'</label>').join(''));formBind('#home-projects',async data=>{await request('/api/ops/home',{page:{title:data.title,description:data.description,heading:data.heading,intro:data.intro,banner:data.banner,deadline:data.deadline?Date.parse(data.deadline):0},projects:qsa('.home-project').map(el=>({id:el.dataset.projectId,visible:qs('.home-visible',el).checked,order:Number(qs('.home-order',el).value),marketOrder:Number(qs('.market-order',el).value)})),featured:qsa('[data-featured-id]:checked').map(el=>el.dataset.featuredId)});notice('Home placement, Marketplace order and featured properties saved.')})};
const nov8Closed=closedScreen;closedScreen=async function(run){await nov8Closed(run);if(run!==screenRun)return;const r=await request('/api/ops/closed-deals');qsa('[data-closed-id]').forEach(el=>{const d=r.deals.find(d=>d.id===el.dataset.closedId);el.insertAdjacentHTML('afterbegin','<p class="closed-fees">Final plot price: '+money(d.final_total||d.amount)+' · Seller service fee (0.5%): '+money(d.seller_fee)+' · Buyer service fee (0.5%): '+money(d.buyer_fee)+'</p>')})};

function deleteUserPrompt(id){const dialog=qs('#staff-dialog');qs('#staff-dialog-content').innerHTML='<h2>Permanently delete user?</h2><p>Type DELETE to confirm. Anonymous transaction records remain.</p><label>Confirmation<input id="delete-user-confirm-text" autocomplete="off" spellcheck="false"></label><p id="staff-confirm-error" role="alert"></p><div class="btn-row"><button class="btn btn-outline" id="staff-cancel">Cancel</button><button class="btn btn-danger" id="staff-confirm" disabled>Delete user permanently</button></div>';const input=qs('#delete-user-confirm-text'),button=qs('#staff-confirm');input.oninput=()=>button.disabled=input.value!=='DELETE';qs('#staff-cancel').onclick=()=>dialog.close();button.onclick=async()=>{button.disabled=true;try{await request('/api/ops/users/'+id+'/delete',{confirm:true,confirmText:input.value});dialog.close();goStaff('/budapest-admin/users')}catch(error){qs('#staff-confirm-error').textContent=error.message;button.disabled=input.value!=='DELETE'}};dialog.showModal();input.focus()}

;
'use strict';
modules.splice(modules.findIndex(m=>m[0]==='home'),0,['project-info','Projects Info','pages'],['formats','Formats','read-formats']);
let staffLive=null,staffLiveTimer=null,staffDirty=false;
const nov9Frame=frame;frame=function(module,title,body){const original=staff.permissions;if(!staff.permissions.includes('read-formats'))staff.permissions=[...staff.permissions,'read-formats'];nov9Frame(module,title,body);staff.permissions=original;staffDirty=false;const main=qs('.staff-main');main.addEventListener('input',()=>staffDirty=true);main.addEventListener('change',()=>staffDirty=true);connectStaffLive()};
function connectStaffLive(){if(staffLive||!staff||staff.mustChange)return;const socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/api/live?scope=staff');staffLive=socket;socket.onmessage=async e=>{let data;try{data=JSON.parse(e.data)}catch{return}if(data.initial)return;await refreshAdminStars();if(!qs('.staff-main'))return;if(staffDirty||qs('#staff-dialog')?.open){const status=qs('#staff-status');if(!qs('#staff-refresh-available')){status.innerHTML='<span class="staff-update-indicator">Updates available <button id="staff-refresh-available" type="button">Load latest</button></span>';qs('#staff-refresh-available').onclick=()=>{if(staffDirty)confirmStaff('Discard unsaved changes and load the latest data?',()=>routeStaff());else routeStaff()}}}else{clearTimeout(staffLiveTimer);staffLiveTimer=setTimeout(()=>routeStaff(),150)}};socket.onclose=()=>{staffLive=null;if(staff&&!staff.mustChange)staffLiveTimer=setTimeout(connectStaffLive,4000)};socket.onerror=()=>socket.close()}
addEventListener('pagehide',()=>{clearTimeout(staffLiveTimer);if(staffLive){staffLive.onclose=null;staffLive.close();staffLive=null}});
async function uploadStaffFile(file,kind){const form=new FormData();form.set('file',file);form.set('kind',kind);form.set('scope','staff');const r=await fetch('/api/uploads',{method:'POST',credentials:'same-origin',body:form}),result=await r.json();if(!r.ok)throw new Error(result.error);return result}
async function projectInfoScreen(run){const r=await request('/api/ops/project-info');if(run!==screenRun)return;frame('project-info','Projects Info','<button class="btn btn-accent" id="add-project-info">Add Project Info</button><div class="staff-project-list">'+r.projects.map(p=>'<article class="panel"><h2>'+html(p.title)+'</h2><p>Tab: '+html(p.tab_name)+' · /projects-info/'+html(p.id)+'</p><label><input type="checkbox" data-info-enabled="'+html(p.id)+'" '+(p.visible?'checked':'')+'> Show project on website</label><p>'+p.images.length+' pictures · Order '+p.sort_order+'</p><div class="btn-row"><button class="btn btn-black" data-edit-info="'+html(p.id)+'">Edit</button><button class="btn btn-danger" data-delete-info="'+html(p.id)+'">Delete</button><a class="btn btn-outline" href="/projects-info/'+html(p.id)+'" target="_blank" rel="noopener">Preview</a></div></article>').join('')+'</div>');qs('#add-project-info').onclick=()=>editProjectInfo(null);qsa('[data-edit-info]').forEach(b=>b.onclick=()=>editProjectInfo(r.projects.find(p=>p.id===b.dataset.editInfo)));qsa('[data-delete-info]').forEach(b=>b.onclick=()=>{const p=r.projects.find(p=>p.id===b.dataset.deleteInfo);confirmStaff('Delete this project information page?',async()=>{await request('/api/ops/project-info/'+p.id+'/delete',{version:p.version,confirm:true});await projectInfoScreen(run)})});qsa('[data-info-enabled]').forEach(b=>b.onchange=async()=>{const p=r.projects.find(p=>p.id===b.dataset.infoEnabled);try{await request('/api/ops/project-info/'+p.id,{...p,tabName:p.tab_name,order:p.sort_order,visible:b.checked});await projectInfoScreen(run)}catch(e){b.checked=!!p.visible;alertError(e)}})}
function editProjectInfo(p){const d=p?structuredClone(p):{tab_name:'',title:'',content:'',images:[],sort_order:0,visible:1};frame('project-info',p?'Edit Project Info':'Add Project Info',`<form class="panel" id="project-info-form"><div class="form-grid">${field('tabName','Project tab name',d.tab_name,'text','required')}${field('title','Project title',d.title,'text','required')}${p?'':field('slug','Page address (letters, numbers and dashes)','','text','required pattern="[a-z0-9][a-z0-9-]*"')}${field('order','Tab order',d.sort_order,'number','min="0" max="1000" required')}</div><label><input name="visible" type="checkbox" ${d.visible?'checked':''}> Show this project on the website</label>${box('content','Project content',d.content)}<p>Separate paragraphs with a blank line. To make text clickable, write <code>[Click here](https://example.com)</code>. Links open in a new tab.</p><h2>Project images</h2><p>Up to five JPEG, PNG or WebP images. Choose a position and alignment for each image.</p><input id="info-upload" type="file" multiple accept="image/jpeg,image/png,image/webp"><div id="info-pictures"></div><div class="btn-row"><button type="submit" class="btn btn-accent">Save Project Info</button><button type="button" class="btn btn-outline" id="cancel-info">Cancel</button></div></form>`);qs('#o-content').required=true;const readImages=()=>qsa('[data-info-image]').forEach((el,i)=>{d.images[i].caption=qs('.info-caption',el).value;d.images[i].position=Number(qs('.info-position',el).value);d.images[i].align=qs('.info-align',el).value});const draw=()=>{const paragraphCount=qs('#o-content').value.split(/\n\s*\n/).filter(Boolean).length;qs('#info-pictures').innerHTML=d.images.map((image,i)=>'<div class="project-info-picture" data-info-image="'+i+'"><img src="'+html(image.url)+'" alt="Uploaded project image"><div><label>Caption<input class="info-caption" value="'+html(image.caption)+'"></label><label>Placement<select class="info-position">'+[[0,'Above content'],...Array.from({length:paragraphCount},(_,i)=>[i+1,'After paragraph '+(i+1)]),[-1,'Below content']].map(([v,label])=>'<option value="'+v+'" '+(v===image.position?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label>Alignment<select class="info-align">'+options(['full','left','right'],image.align)+'</select></label><div class="btn-row"><button type="button" class="btn btn-outline" data-info-move="'+i+':-1">↑</button><button type="button" class="btn btn-outline" data-info-move="'+i+':1">↓</button><button type="button" class="btn btn-outline" data-remove-info-image="'+i+'">Remove image</button></div></div></div>').join('');qsa('[data-remove-info-image]').forEach(b=>b.onclick=()=>{readImages();d.images.splice(Number(b.dataset.removeInfoImage),1);draw()});qsa('[data-info-move]').forEach(b=>b.onclick=()=>{readImages();const [i,dir]=b.dataset.infoMove.split(':').map(Number),j=i+dir;if(j<0||j>=d.images.length)return;[d.images[i],d.images[j]]=[d.images[j],d.images[i]];draw()})};draw();qs('#info-upload').onchange=async e=>{const button=qs('#project-info-form [type=submit]');button.disabled=true;try{readImages();if(d.images.length+e.target.files.length>5)throw new Error('Choose up to five pictures.');for(const file of e.target.files){const upload=await uploadStaffFile(file,'image');d.images.push({url:upload.url,caption:'',align:'full',position:-1})}draw();e.target.value=''}catch(error){alertError(error)}finally{button.disabled=false}};qs('#cancel-info').onclick=()=>routeStaff();formBind('#project-info-form',async data=>{readImages();await request('/api/ops/project-info'+(p?'/'+p.id:''),{...data,visible:qs('[name=visible]').checked,images:d.images,version:p?.version});staffDirty=false;await routeStaff()})}
async function formatsScreen(run){const r=await request('/api/ops/formats');if(run!==screenRun)return;const edit=staff.permissions.includes('settings');frame('formats','Formats',(edit?'<button class="btn btn-accent" id="add-format">Upload document</button>':'')+'<div class="format-list">'+r.formats.map(f=>'<article class="panel"><h2>'+html(f.name)+'</h2><p>'+html(f.description).replace(/\n/g,'<br>')+'</p><small>'+html(f.filename)+' · '+Math.ceil(f.size/1024)+' KB · '+when(f.updated_at)+'</small><div class="btn-row"><a class="btn btn-black" href="/api/media/'+html(f.attachment_id)+'" download>Download document</a>'+(edit?'<button class="btn btn-outline" data-edit-format="'+html(f.id)+'">Edit</button><button class="btn btn-danger" data-delete-format="'+html(f.id)+'">Delete</button>':'')+'</div></article>').join('')+'</div>');qs('#add-format')?.addEventListener('click',()=>editFormat(null));qsa('[data-edit-format]').forEach(b=>b.onclick=()=>editFormat(r.formats.find(f=>f.id===b.dataset.editFormat)));qsa('[data-delete-format]').forEach(b=>b.onclick=()=>{const f=r.formats.find(f=>f.id===b.dataset.deleteFormat);confirmStaff('Delete this staff format?',async()=>{await request('/api/ops/formats/'+f.id+'/delete',{version:f.version,confirm:true});await formatsScreen(run)})})}
function editFormat(f){let attachmentId=f?.attachment_id;frame('formats',f?'Edit Format':'Upload Format',`<form id="format-form" class="panel">${field('name','Document name',f?.name||'','text','required')}${box('description','Description',f?.description||'')}<label>Document (PDF, DOCX or XLSX; up to 10 MB)<input id="format-file" type="file" accept=".pdf,.docx,.xlsx" ${f?'':'required'}></label><p id="format-upload-status">${f?html(f.filename):''}</p><button type="submit" class="btn btn-accent">Save document</button></form>`);qs('#format-file').onchange=async e=>{const b=qs('#format-form [type=submit]');b.disabled=true;try{const upload=await uploadStaffFile(e.target.files[0],'format');attachmentId=upload.id;qs('#format-upload-status').textContent='Uploaded: '+upload.name}catch(error){attachmentId=f?.attachment_id;e.target.value='';alertError(error)}finally{b.disabled=false}};formBind('#format-form',async data=>{if(!attachmentId)throw new Error('Upload a document first.');await request('/api/ops/formats'+(f?'/'+f.id:''),{...data,attachmentId,version:f?.version});staffDirty=false;await routeStaff()})}
closedScreen=async function(run){const r=await request('/api/ops/closed-deals');if(run!==screenRun)return;frame('closed-deals','View Closed Deals','<div class="staff-toolbar"><p>'+r.deals.length+' closed deals. Open a row for contact details and the documentation checklist.</p><a class="btn btn-black" href="/api/ops/closed-deals?export=1" download>Download Excel</a></div><div class="wide-table"><table class="closed-deals-table"><thead><tr><th>Property ID / Title</th><th>Buyer Bidding ID</th><th>Final price</th><th>Seller fee</th><th>Buyer fee</th><th>Accepted</th><th>Details</th></tr></thead><tbody>'+r.deals.map(d=>{const checklist=JSON.parse(d.checklist||'{}');return '<tr data-closed-id="'+html(d.id)+'"><td>'+html(d.property_id)+'<br>'+html(d.property_title)+'</td><td>'+html(d.bidding_id||'Not assigned')+'</td><td>'+money(d.final_total||d.amount)+'</td><td>'+money(d.seller_fee)+' (0.5%)</td><td>'+money(d.buyer_fee)+' (0.5%)</td><td>'+html(when(d.created_at).slice(0,12))+'<br>'+html(when(d.created_at).slice(13))+'</td><td><button class="btn btn-outline" type="button" aria-expanded="false" data-open-deal="'+html(d.id)+'">Open deal</button></td></tr><tr hidden data-deal-detail="'+html(d.id)+'"><td colspan="7"><div class="closed-detail"><p>Buyer: '+html(d.buyer_name)+' · '+html(d.buyer_email)+' · '+html(d.buyer_phone)+'</p><p>Seller: '+html(d.seller_name)+' · '+html(d.seller_email)+' · '+html(d.seller_phone)+'</p><p>Accepted by: '+html(d.accepted_by)+' · '+html(d.source)+'</p><p>Refer to Property ID: '+html(d.property_id)+' during office visits.</p><form data-checklist="'+html(d.id)+'">'+[['buyerContacted','Buyer contacted'],['sellerContacted','Seller contacted'],['dealFinalized','Deal finalized'],['documentationCompleted','Documentation completed']].map(([key,label])=>'<label><input type="checkbox" name="'+key+'" '+(checklist[key]?'checked':'')+'> '+label+'</label>').join('')+'<button class="btn btn-accent" type="submit">Save checklist</button></form></div></td></tr>'}).join('')+'</tbody></table></div>');qsa('[data-open-deal]').forEach(b=>{const detail=qsa('[data-deal-detail]').find(el=>el.dataset.dealDetail===b.dataset.openDeal);b.onclick=()=>{detail.hidden=!detail.hidden;b.setAttribute('aria-expanded',String(!detail.hidden));b.textContent=detail.hidden?'Open deal':'Close details'};const row=b.closest('tr');row.tabIndex=0;row.onclick=e=>{if(!e.target.closest('button,a,input'))b.click()};row.onkeydown=e=>{if(e.key==='Enter'&&e.target===row)b.click()}});qsa('[data-checklist]').forEach(form=>formBind('[data-checklist="'+form.dataset.checklist+'"]',async()=>{const d=r.deals.find(d=>d.id===form.dataset.checklist);await request('/api/ops/closed-deals/'+d.id,{version:d.version,checklist:Object.fromEntries([...form.elements].filter(e=>e.type==='checkbox').map(e=>[e.name,e.checked]))});staffDirty=false;await closedScreen(run)}))};
